'use strict';
// Friendship stories, lasting world projects, memorials and portable adventure saves.
const legacy={ready:false,stories:{},monuments:[],scene:null,trial:null,autosave:0,lastSaved:'',freshConfirm:false,bonds:{},memorialScene:null,bondScene:null,playerName:'Wanderer',afterDeath:0,witnesses:{},errands:{},powerScene:null,pendingWitness:null,tracked:null,trailBridges:[],mapTimer:0};
const legacySaveKey='mossbound-adventure-v1',legacyBackupKey='mossbound-adventure-backup-v1';
const legacyStories={
 mira:{title:'A place to grow',intro:'I kept these seeds through every winter. At last, there is someone I trust to plant them with me. What should our garden become?',choices:['A berry garden for everyone','A wild garden full of nectar'],costs:[{3:12,berries:4},{3:12,nectar:4}],goal:'Bring supplies to Mira to plant the garden.',reward:'A living garden · harvest once each day',lines:['You loosen the soil while Mira opens a small, carefully folded packet. Together, you plant the first row.','“These are not emergency supplies anymore,” Mira says. “They are something to look forward to. Come back tomorrow. We will have enough to share.”']},
 rowan:{title:'The bridge beyond',intro:'There is an old lookout past the broken bridge. I stopped going when the ropes frayed. I would like to see that view with you.',choices:['Build with sturdy anchors','Weave a light rope bridge'],costs:[{3:16,rope:4},{3:10,rope:8}],goal:'After building, cross the new bridge east of Wren’s Perch. Press I at the lookout, x 211.',reward:'A hidden lookout · Swift Boots and 12 torches',lines:['Rowan tests the last knot, then walks beside you to the lookout. Neither of you speaks for a while.','“I used to think surviving meant staying where it was safe. You reminded me that there are still places worth reaching.” He leaves a lantern here, just for you.']},
 bram:{title:'A heartbeat underground',intro:'Something is tapping beyond the old mine. Not a monster. A little tunneler, trapped behind a cave-in. Help me find it?',choices:['Shore up the careful route','Follow the tapping directly'],costs:[{3:12,torch:6},{2:16,torch:4}],goal:'Enter the new mine east of Buried Lantern. Follow its lanterns to x 452, y 57, then press I.',reward:'Moleback mount · Q dash digs natural ground',lines:['The last stones come loose. A dusty mole the size of a pony tumbles into Bram’s arms and immediately steals a snack.','“It chose you,” Bram laughs, fastening a spare saddle. “A good friend makes even the deepest tunnel feel less lonely.” The Moleback is yours to ride.']},
 iona:{title:'One more lantern',intro:'A traveler named Elian is hiding in the ruins west of the coast. I cannot leave the shelter unattended. Will you bring them home?',choices:['Pack a warm shelter kit','Pack a field medicine kit'],costs:[{healPotion:2,stew:1,3:6},{healPotion:3,stew:1}],goal:'Find Elian at the roadside ruin, x 235. Press I beside the lantern to escort them home.',reward:'A seventh survivor · Elian joins Buried Lantern',lines:['You reach the shelter together. Iona sets another bowl beside the kettle before asking a single question.','“I thought I was the last one,” Elian whispers. Iona lights a third lantern. “You are home now. There is room.”']},
 suri:{title:'Where the wind remembers',intro:'I built a little flight course above the canopy. I never found anyone I wanted to share the sky with. Until now.',choices:['Take the low, gentle route','Chase the high wind'],costs:[{nectar:4,3:6},{nectar:6}],goal:'Return to Suri to start a 40-second flight trial. Fly through three glowing wind rings in order.',reward:'Canopy Wings · an improved slow-fall glider',lines:['You catch the last current and Suri raises both arms from the lookout. For a moment the whole canopy seems to cheer.','“I stitched these wings for you.” Their cloth catches the breeze, bright as new leaves. “When you are out there, remember someone is watching for your return.”']},
 tavi:{title:'A table with room',intro:'I want to cook a proper dinner. Not because we need to eat. Because we are still here. What should we toast to?',choices:['The friends still beside us','The people we remember'],costs:[{stew:3,berryPie:2},{stew:2,fishSoup:2,berries:4}],goal:'Bring the meal to Tavi and share supper beside the canopy fire.',reward:'A shared supper table · everyone gains friendship · daily meals',lines:['Lanterns are hung. Bowls are passed around the fire. Stories wander from the ridiculous to the tender, and nobody rushes to leave.','Tavi places a bowl at the empty seat. “For whoever comes next. And for the ones who got us this far.” Tonight, the wilds feel a little less empty.']}
};
function legacyState(id){return legacy.stories[id]||(legacy.stories[id]={stage:0,choice:0,day:-1})}
function legacyBusy(){if($('legacy-panel').classList.contains('hidden')){legacy.scene=null;legacy.memorialScene=null;legacy.bondScene=null;legacy.powerScene=null}return !!(boss||bossIntro||adminReckoning||skyTrial||legacy.scene||legacy.powerScene||legacy.memorialScene||legacy.bondScene||legacy.trial||codeWeapon.terrain||codeWeapon.domain||codeWeapon.rain.length||codeWeapon.rewrites.size||codeInputActive())}
function initializeLegacy(){if(legacy.ready)return;legacy.ready=true;mounts.push({name:'Moleback',speed:225,jump:390,fly:false,color:'#9e8879',detail:'Bram’s five-heart story · a loyal cave companion · Q dash digs nearby natural ground'});trust.push(0);initializeLivingWorld();items.canopyWings={name:'Canopy Wings',type:'accessory',detail:'Hold jump while falling · gentler glide than a Wind Glider',source:'Suri’s five-heart wind trial'};
$('survivor-story-button').onclick=()=>activeSurvivor&&openLegacyStory(activeSurvivor.id);
$('survivor-garden-button').onclick=harvestLegacyProject;
$('memories-button').onclick=()=>{if(started)openLegacyMemories()};
$('save-menu-button').onclick=()=>{panel('save-panel');legacySaveStatus()};
$('save-now').onclick=()=>saveLegacyGame(true);
$('save-export').onclick=exportLegacySave;
$('save-backup').onclick=()=>{try{const raw=localStorage.getItem(legacyBackupKey);if(!raw)throw Error('No previous backup yet.');loadLegacyAdventure(raw);$('save-status').textContent='Previous backup restored.'}catch(e){$('save-status').textContent=e.message}};
$('save-import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>6000000)throw Error('This file is too large. Choose a Mossbound save.');loadLegacyAdventure(await f.text());notify('Adventure imported. Your old save is kept as a backup.')}catch(error){$('save-status').textContent='Could not import: '+error.message}e.target.value=''});
const start=$('start').onclick;$('start').onclick=()=>{if(legacy.freshConfirm||!legacyStored()){legacy.freshConfirm=false;if(legacyStored())localStorage.setItem(legacyBackupKey,localStorage.getItem(legacySaveKey));start();saveLegacyGame(false)}else{legacy.freshConfirm=true;$('start').textContent='Start fresh · keep old save as backup';$('continue-status').textContent='Click again for a fresh world, or Continue to keep playing your saved adventure.'}};
$('continue-save').onclick=()=>{try{loadLegacyAdventure(localStorage.getItem(legacySaveKey))}catch(e){$('continue-status').textContent='Could not load: '+e.message+' You can import a backup through Save.'}};
$('avatar-name').value=legacy.playerName;$('avatar-name').onchange=()=>{legacy.playerName=cleanLegacyName($('avatar-name').value);$('avatar-name').value=legacy.playerName;if(started)saveLegacyGame(false)};$('survivor-heart-button').onclick=()=>activeSurvivor&&openBondEvent(activeSurvivor.id);window.addEventListener('pagehide',()=>{if(started)saveLegacyGame(false)});refreshLegacyContinue();
}
function legacyStored(){try{return !!localStorage.getItem(legacySaveKey)}catch{return false}}
function refreshLegacyContinue(){try{const raw=localStorage.getItem(legacySaveKey);if(!raw)return;const data=JSON.parse(raw);if(data.version!==1)return;$('continue-save').classList.remove('hidden');$('continue-status').textContent='Saved adventure · day '+(Math.floor((data.time||0)/240)+1)+' · '+(data.monuments?.length||0)+' monuments';$('start').textContent='New adventure'}catch{}}
function renderLegacyStoryButton(n){renderBondButton(n);renderPowerFriendship(n);const d=legacyStories[n.id],b=$('survivor-story-button'),h=$('survivor-story-hint'),g=$('survivor-garden-button');g.classList.add('hidden');if(!d){h.textContent='Thank you for bringing me home. Another light is burning because of you.';b.disabled=true;b.textContent='A new beginning';return}const s=legacyState(n.id);h.textContent=d.title+' · '+(s.stage===3?'A memory you share. '+d.reward:n.friend<100?'Reach five full hearts with talk, favorite gifts and requests.':s.stage?d.goal:'A personal story is ready.');b.disabled=n.friend<100||s.stage===3;b.textContent=s.stage===3?'Story complete':s.stage===2?'Share this moment':s.stage===1?'Continue our story':'Begin personal story';if(s.stage===3&&['mira','tavi'].includes(n.id)){g.classList.remove('hidden');g.disabled=s.day===survivorDay();g.textContent=s.day===survivorDay()?'Shared today · return tomorrow':n.id==='mira'?'Harvest our garden':'Share a meal at our table'}}
function legacyCanTalk(id){const n=survivors.find(n=>n.id===id);return started&&p.hp>0&&!boss&&!bossIntro&&!adminReckoning&&n&&nearSurvivor()===n?n:null}
function openLegacyStory(id){const n=legacyCanTalk(id),d=legacyStories[id];if(!n||!d||n.friend<100)return false;const s=legacyState(id);if(s.stage===3)return false;legacy.scene={id,index:0,finishing:s.stage===2};panel('legacy-panel');renderLegacyScene();return true}
function renderLegacyScene(){$('legacy-panel').classList.remove('monument-cinema');const scene=legacy.scene;if(!scene)return;const id=scene.id,d=legacyStories[id],s=legacyState(id),n=survivors.find(n=>n.id===id);$('legacy-speaker').textContent=n.name+' · FIVE HEARTS';$('legacy-title').textContent=d.title;$('legacy-feedback').textContent='';const choices=$('legacy-choice-list');choices.innerHTML='';const next=$('legacy-advance');next.classList.remove('hidden');next.disabled=false;
if(scene.finishing){$('legacy-text').textContent=d.lines[scene.index];$('legacy-objective').textContent='Your choice: '+d.choices[s.choice]+' · '+d.reward;next.textContent=scene.index===d.lines.length-1?'Keep this memory':'Continue';next.onclick=()=>{if(!legacyCanTalk(id))return;if(++scene.index<d.lines.length)renderLegacyScene();else completeLegacyStory(id)};return}
$('legacy-text').textContent=d.intro;
if(s.stage===0){$('legacy-objective').textContent='Choose how this story unfolds. Each path has its own supplies.';next.classList.add('hidden');d.choices.forEach((label,i)=>{const b=document.createElement('button');b.textContent=label+' · '+survivorCostText(d.costs[i]);b.onclick=()=>{if(!legacyCanTalk(id)||legacyState(id).stage!==0)return;s.stage=1;s.choice=i;legacy.scene=null;saveLegacyGame(false);legacy.scene={id,index:0,finishing:false};renderLegacyScene()};choices.appendChild(b)})}else{$('legacy-objective').textContent=d.goal+'\nChosen: '+d.choices[s.choice]+(s.prepared?' · Supplies delivered.':'\nNeed: '+survivorCostText(d.costs[s.choice]));next.textContent=!s.prepared?'Deliver supplies':id==='suri'?'Start wind trial':'Return to the trail';next.disabled=!s.prepared&&!survivorCanPay(d.costs[s.choice]);next.onclick=()=>advanceLegacyObjective(id)}}
function advanceLegacyObjective(id){if(!legacyCanTalk(id))return false;const s=legacyState(id),d=legacyStories[id];if(s.stage!==1)return false;if(!s.prepared){if(!survivorCanPay(d.costs[s.choice]))return false;survivorPay(d.costs[s.choice]);s.prepared=true;buildLegacyProject(id);inventory();updatePack();if(['mira','tavi'].includes(id)){s.stage=2;legacy.scene={id,index:0,finishing:true};renderLegacyScene();return true}if(id==='suri'){renderLegacyScene();return true}legacy.scene=null;closePanels();saveLegacyGame(false);notify(d.goal);return true}legacy.scene=null;closePanels();if(id==='suri')startLegacyTrial();else notify(d.goal);return true}
function buildLegacyProject(id){const s=legacyState(id);if(id==='rowan'){const f=settlements[0].floor;for(let x=189;x<=214;x++){for(let y=f-4;y<f;y++)set(x,y,0);set(x,f,17)}}if(id==='bram'){const v=settlements[1];for(let x=440;x<=455;x++){const f=v.floor+Math.floor((x-440)*.75);for(let y=f-4;y<f;y++)set(x,y,0);set(x,f,15);if(x%3===0)torches.push({x,y:f-2})}for(let x=449;x<=456;x++){for(let y=53;y<58;y++)set(x,y,0);set(x,58,15)}}if(id==='iona'&&s.stage===3)rescueLegacyElian()}
function legacyProtected(x,y){if(legacy.trailBridges.some(b=>x>=b.left&&x<=b.right&&y===b.y))return true;const r=legacy.stories.rowan,b=legacy.stories.bram;return !!(r?.prepared&&x>=189&&x<=214&&y>=settlements[0].floor-1&&y<=settlements[0].floor+1||b?.prepared&&x>=439&&x<=457&&y>=settlements[1].floor-5&&y<=60)}
function completeLegacyStory(id){const s=legacyState(id);if(s.stage!==2)return false;s.stage=3;legacy.scene=null;legacy.trial=null;closePanels();if(id==='rowan'){owned.add('swiftBoots');survivorGive({torch:12})}if(id==='bram'){tamed.add(4);trust[4]=3;mountChoice=4}if(id==='iona')rescueLegacyElian();if(id==='suri'){owned.add('canopyWings');accessories.add('canopyWings')}if(id==='tavi'){for(const n of survivors)n.friend=Math.min(100,n.friend+10);survivorGive({stew:3,berryPie:2})}saveSurvivorHearts();inventory();updatePack();updateAdventure();updatePeopleJournal();saveLegacyGame(false);notify('A memory made · '+legacyStories[id].reward);beep(720);return true}
function rescueLegacyElian(){if(survivors.some(n=>n.id==='elian'))return;const d={id:'elian',name:'Elian',role:'Rescued traveler',home:1,skin:'#cfa180',hair:'#3d3e51',shirt:'#7895ad',pants:'#5d5b69',favorite:'grilled',task:'A bed of my own',need:{3:12},reward:{fishSoup:3},lines:['A kettle, a roof, and people who know my name. I had forgotten what home felt like.','Bram showed me the pump. Iona lets me help with the medicine. I am learning how to stay.','You came back for me. When the lanterns go dim, that is what I remember.'],request:'Twelve wood would make a small bed. I will cook you fish soup in return.',thanks:'A place of my own. Thank you for making room for me.',trade:{cost:{fish:2},give:{fishSoup:1},label:'Traveler’s fish soup'},hat:'scarf'};survivorProfiles.push(d);const v=settlements[1];survivors.push({...d,x:v.tile*T,y:v.floor*T,w:13,h:29,friend:40,quest:0,talkDay:-1,giftDay:-1,tradeDay:-1,stock:3,face:1,walk:0,moving:false,activity:'Warming by the kettle',line:'',bubble:4});v.story='Three survivors keeping the lanterns alive beneath the coast.'}
function harvestLegacyProject(){const n=activeSurvivor;if(!n||!legacyCanTalk(n.id))return false;const s=legacyState(n.id);if(s.stage!==3||s.day===survivorDay()||!['mira','tavi'].includes(n.id))return false;s.day=survivorDay();const reward=n.id==='mira'?s.choice?{nectar:6,berries:2}:{berries:8,nectar:2}:{stew:2,berryPie:1};survivorGive(reward);if(n.id==='tavi'){p.hp=Math.min(100,p.hp+20);hunger=20}inventory();updatePack();renderSurvivorPanel();$('survivor-result').textContent='Shared with a friend · '+survivorCostText(reward);saveLegacyGame(false);return true}
function legacyMarkers(){const out=[],r=legacy.stories.rowan,b=legacy.stories.bram,i=legacy.stories.iona;if(r?.prepared&&r.stage===1)out.push({id:'rowan',x:211*T,y:settlements[0].floor*T,label:'Rowan’s lookout'});if(b?.prepared&&b.stage===1)out.push({id:'bram',x:452*T,y:58*T,label:'Trapped Moleback'});if(i?.prepared&&i.stage===1)out.push({id:'iona',x:235*T,y:surface[235]*T,label:'Elian · rescue'});return out}
function interactLegacy(){if(!started||paused||boss||bossIntro||adminReckoning||p.hp<=0)return false;const point=legacyMarkers().find(m=>Math.hypot(p.x+p.w/2-m.x,p.y+p.h-m.y)<85);if(point){legacyState(point.id).stage=2;if(point.id==='iona')notify('Elian follows the lanterns to safety. Return to Iona at Buried Lantern.');else notify('You found it! Return to '+survivors.find(n=>n.id===point.id).name+' to share this moment.');saveLegacyGame(false);return true}const m=nearLegacyMonument();if(m){if(!m.seen){startMonumentScene(m);return true}if(!m.visited){m.visited=true;p.hp=Math.min(100,p.hp+15);saveLegacyGame(false)}openLegacyMemories(m);return true}return false}
function legacyTrialPoints(){const v=settlements[2],high=legacyState('suri').choice?5:0;return [{x:(v.tile-10)*T,y:(v.floor-4-high)*T},{x:(v.tile+3)*T,y:(v.floor-8-high)*T},{x:(v.tile+13)*T,y:(v.floor-5-high)*T}]}
function startLegacyTrial(){if(legacyState('suri').stage!==1||!legacyState('suri').prepared)return false;legacy.trial={remaining:40,index:0};notify('Wind trial · fly through 3 glowing rings in order · 40 seconds');return true}
function tickLegacy(dt){if(!legacy.ready)return;tickLivingWorld(dt);legacy.afterDeath=Math.max(0,legacy.afterDeath-dt);if($('legacy-panel').classList.contains('hidden')){legacy.memorialScene=null;legacy.bondScene=null}if(!paused&&!legacyBusy()&&legacy.afterDeath<=0){const unseen=legacy.monuments.find(m=>!m.seen&&Math.hypot(p.x+p.w/2-m.x,p.y+p.h-m.y)<170&&Math.abs(p.y+p.h-m.y)<100);if(unseen){startMonumentScene(unseen);return}}if(legacy.scene&&$('legacy-panel').classList.contains('hidden'))legacy.scene=null;if(legacy.trial){const tr=legacy.trial,pt=legacyTrialPoints()[tr.index];tr.remaining-=dt;if(p.hp<=0||tr.remaining<=0){legacy.trial=null;notify('The wind moved on. Talk to Suri to try again.')}else if(Math.hypot(p.x+p.w/2-pt.x,p.y+p.h/2-pt.y)<40){tr.index++;burst(pt.x,pt.y,'#b0efce',12);if(tr.index===3){legacy.trial=null;legacyState('suri').stage=2;notify('Wind trial complete! Return to Suri for your wings.');saveLegacyGame(false)}else notify('Wind ring '+tr.index+'/3 · '+Math.ceil(tr.remaining)+'s left')}}legacy.autosave+=dt;if(legacy.autosave>=20&&!legacyBusy()){legacy.autosave=0;saveLegacyGame(false)}if(!paused&&!boss){const date=friendshipDate();$('clock').textContent+=' · '+date.season+' '+date.date;const point=legacyMarkers().find(m=>Math.hypot(p.x-m.x,p.y+p.h-m.y)<85),m=nearLegacyMonument();if(point||m){$('sky-talk').classList.remove('hidden');$('sky-talk').textContent=point?point.label+' · I':'Remember this life · I'}if(legacy.trial){$('location').textContent='Suri’s wind trial · '+legacy.trial.index+'/3';$('depth').textContent=Math.ceil(legacy.trial.remaining)+' seconds · fly through the glowing ring'}}}
function recordLegacyDeath(){if(!legacy.ready)return;const x=Math.max(T,Math.min((W-2)*T,p.x+p.w/2)),feet=Math.max((-SKY+3)*T,Math.min((H-4)*T,p.y+p.h));let y=feet;for(let j=0;j<15;j++){const ty=Math.floor(feet/T)+j;if(ty>=H-3)break;if(solid(Math.floor(x/T),ty)||get(Math.floor(x/T),ty)===17){y=ty*T;break}}const friend=survivors.filter(n=>n.friend>=60).sort((a,b)=>b.friend-a.friend)[0];legacy.monuments.push({id:legacy.monuments.length+1,x,y,day:Math.floor(time/240)+1,zone:biomeAt(x),cause:lastDeathCause==='drowning'?'Drowned in the deep':lastDeathCause==='admin'?'The Admin’s final trial':boss?'Fell fighting '+(bossDefs[boss.id]?.name||boss.name||'a guardian'):'Lost to the wilds',friend:friend?.id||'',visited:false,seen:false,name:legacy.playerName,golden:adminUnlocked||admin.god,avatar:{...avatar}});legacy.trial=null;legacy.scene=null;legacy.afterDeath=3}
function nearLegacyMonument(){return legacy.monuments.slice().reverse().find(m=>Math.hypot(p.x+p.w/2-m.x,p.y+p.h-m.y)<65)}
function openLegacyMemories(focus){panel('memorial-panel');$('memorial-title').textContent=focus?'A life remembered':'Your monuments';$('memorial-summary').textContent=legacy.monuments.length?legacy.monuments.length+' lives remembered. Monuments remain where you fell. Press I beside one to pay respects and recover 15 health once.':'No monuments yet. When you fall, a stone memorial will mark that place. Your equipment stays with you.';const list=$('memorial-list');list.innerHTML='';const records=focus?[focus]:legacy.monuments.slice().reverse();for(const m of records){const div=document.createElement('div');div.className='memory-entry';const title=document.createElement('h3');title.textContent=(m.golden?'✦ Golden monument · ':'')+(m.name||'Wanderer')+' · Life '+m.id+' · Day '+m.day+' · '+biomes[m.zone].name;const text=document.createElement('p');text.textContent=m.cause+' · x '+Math.floor(m.x/T)+', y '+Math.floor(m.y/T)+(m.visited?' · Respects paid':'');div.appendChild(title);div.appendChild(text);if(m.friend){const q=document.createElement('p'),n=survivors.find(n=>n.id===m.friend);q.textContent=(n?.name||'A friend')+' left flowers: “You mattered here. Come home when you can.”';div.appendChild(q)}list.appendChild(div)}}
function renderLegacyJournal(){if(!legacy.ready)return;const root=$('legacy-journal');root.innerHTML='';for(const [id,d]of Object.entries(legacyStories)){const n=survivors.find(n=>n.id===id),s=legacyState(id),e=document.createElement('div');e.className='legacy-journal-entry';const h=document.createElement('h3');h.textContent=n.name+' · '+d.title;const p1=document.createElement('p');p1.textContent=s.stage===3?'Complete · '+d.reward:s.stage===2?'Return to '+n.name+' to share this moment.':s.stage===1?d.goal+(s.prepared?' · Supplies delivered.':' · Need '+survivorCostText(d.costs[s.choice])):'Five hearts unlock this story · '+survivorHearts(n);e.appendChild(h);e.appendChild(p1);const notes=document.createElement('p'),b=bondState(id);notes.textContent=friendshipTitle(n)+' · Heart memories: '+(b.events.length?b.events.map(l=>l+' hearts').join(', '):'none yet')+' · Birthday: day '+bondProfiles[id].birthday+' each season';e.appendChild(notes);root.appendChild(e)}renderJourneyJournal();}
