function encodeLegacyTiles(a){const bytes=[];for(let i=0;i<a.length;){const v=a[i];let n=1;while(i+n<a.length&&a[i+n]===v&&n<65535)n++;bytes.push(v,n&255,n>>8);i+=n}let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.slice(i,i+8192));return btoa(raw)}
