function cleanLegacyName(value){return typeof value==='string'?value.replace(/[<>\x00-\x1f]/g,'').trim().slice(0,24)||'Wanderer':'Wanderer'}
function startMonumentScene(m){if(paused||boss||bossIntro||adminReckoning||legacy.scene||legacy.bondScene)return false;legacy.memorialScene={id:m.id,index:0};panel('legacy-panel');$('legacy-panel').classList.add('monument-cinema');keysClear();renderMonumentScene();return true}
function renderMonumentScene(){const sc=legacy.memorialScene,m=legacy.monuments.find(m=>m.id===sc?.id);if(!m)return;const name=m.name||'Wanderer',lines=['You stop beside the weathered monument. The world seems to grow quiet.','A name is carved into '+(m.golden?'the shining gold':'the stone')+': '+name+'.','“Why does this name look so familiar?”','For a moment, you remember falling here. Another life. The same hands. The same name.'+(m.golden?' The gold answers with a faint pulse, as if it recognizes its creator.':'')];$('legacy-speaker').textContent=m.golden?'A GOLDEN ECHO':'AN ECHO OF YOURSELF';$('legacy-title').textContent='A familiar name';$('legacy-text').textContent=lines[sc.index];$('legacy-objective').textContent='Day '+m.day+' · '+biomes[m.zone].name+' · '+name;$('legacy-choice-list').innerHTML='';$('legacy-feedback').textContent='';const b=$('legacy-advance');b.classList.remove('hidden');b.disabled=false;b.textContent=sc.index===3?'Remember, and keep going':'Continue';b.onclick=()=>{if(legacy.memorialScene!==sc)return;if(++sc.index<lines.length)renderMonumentScene();else{m.seen=true;legacy.memorialScene=null;closePanels();saveLegacyGame(false);notify('A familiar name. A life remembered.')}}}
function drawMonumentCinema(){const sc=legacy.memorialScene;if(!sc)return;const m=legacy.monuments.find(m=>m.id===sc.id);if(!m)return;ctx.save();ctx.fillStyle='#071018bb';ctx.fillRect(0,0,vw,42);ctx.fillRect(0,vh-52,vw,52);const x=m.x-camera.x,y=m.y-camera.y;const glow=ctx.createRadialGradient(x,y-20,3,x,y-20,90);glow.addColorStop(0,m.golden?'#ffe29a66':'#b1d9ea55');glow.addColorStop(1,'#b1d9ea00');ctx.fillStyle=glow;ctx.fillRect(x-90,y-110,180,180);if(sc.index>=2){ctx.globalAlpha=.35;drawSurvivorSprite(ctx,{...(m.avatar||avatar),skin:m.avatar?.skin||avatar.skin,hair:m.avatar?.hair||avatar.hair,shirt:m.avatar?.shirt||avatar.shirt,pants:m.avatar?.pants||avatar.pants,face:1,moving:false},x+32,y,1.25)}ctx.restore()}
