function bondState(id){return legacy.bonds[id]||(legacy.bonds[id]={events:[],preferences:{},choices:{}})}
function friendshipTitle(n){return n.friend>=100?'Trusted companion':n.friend>=80?'Close friend':n.friend>=60?'Friend':n.friend>=40?'Growing trust':n.friend>=20?'Acquaintance':'New face'}
function friendshipDate(){const day=survivorDay();return {season:['Bloom','Sunhigh','Harvest','Longnight'][Math.floor(day/28)%4],date:day%28+1,year:Math.floor(day/112)+1}}
function legacyGiftResponse(n,gift){const profile=bondProfiles[n.id]||bondProfiles.mira,birthday=friendshipDate().date===profile.birthday;const type=gift===n.favorite?'loved':profile.likes.includes(gift)?'liked':profile.dislikes.includes(gift)?'disliked':'neutral';bondState(n.id).preferences[gift]=type;const points={loved:18,liked:10,neutral:6,disliked:-4}[type]*(birthday?2:1);return{points,birthday,line:(birthday?'“You remembered my birthday!” ':'')+{loved:'“You remembered my favorite. That means more than you know.”',liked:'“Oh, I love sharing this after a long day. Thank you.”',neutral:'“Thank you for thinking of me. Stay a little while?”',disliked:'“I appreciate the thought, but this is not really for me.”'}[type]}}
function legacyGreeting(n){const field=journeyGreeting(n);if(field)return field;const day=survivorDay(),d=friendshipDate(),bond=bondState(n.id),rank=Math.min(2,Math.floor(n.friend/35));if(d.date===bondProfiles[n.id]?.birthday)return '“It is my birthday today. I did not expect anyone to remember. It is good to see you, '+legacy.playerName+'.”';if(legacy.stories[n.id]?.stage===3){const lines={mira:'“Our garden looks a little brighter today. There is a place for you beside it.”',rowan:'“The lantern at our lookout is still burning. I checked it for you.”',bram:'“How is our little tunneler? I saved a snack for your next visit.”',iona:'“Another bowl, another lantern. You helped this shelter become a home.”',suri:'“I watch for your wings above the trees. Come back when the wind gets lonely.”',tavi:'“Your chair is ready. I am making enough for everyone this time.”'};return lines[n.id]||n.lines[rank]}const daily=[n.lines[rank], '“'+legacy.playerName+', you made it back. '+(time%240>=160?'Stay near the lanterns tonight.':'The trail was quiet this morning.')+'”',n.home===1?'“The kettle is on. Down here, a familiar voice carries a long way.”':'“'+(d.season==='Longnight'?'The nights are long, but we still have a fire.':d.season==='Harvest'?'The leaves are turning. It feels like time is moving again.':'There is a little more life in the branches today.')+'”',bond.events.length?rememberBondChoice(n):n.lines[rank]];return daily[(day+survivorProfiles.findIndex(v=>v.id===n.id))%daily.length]}
function renderBondButton(n){if(!legacy.ready)return;const d=friendshipDate(),profile=bondProfiles[n.id],s=bondState(n.id),level=[2,4].find(l=>n.friend>=l*20&&!s.events.includes(l)),b=$('survivor-heart-button');$('survivor-birthday').textContent=friendshipTitle(n)+' · '+d.season+' '+d.date+' · Birthday: day '+(profile?.birthday||1)+' of each season'+(d.date===profile?.birthday?' · BIRTHDAY TODAY · gifts count double!':'');const known=Object.entries(s.preferences).map(([id,type])=>(foods[id]?.name||id)+': '+type);$('survivor-preferences').textContent=known.length?'Gift notes · '+known.join(' · '):'Gift notes · Try different foods to discover their tastes.';b.classList.toggle('hidden',!level);b.textContent=level?'Share a '+level+'-heart moment':'Heart moments shared'}
function openBondEvent(id){if(!legacyCanTalk(id))return false;const n=survivors.find(n=>n.id===id),s=bondState(id),level=[2,4].find(l=>n.friend>=l*20&&!s.events.includes(l));if(!level||!bondProfiles[id])return false;legacy.bondScene={id,level,choice:null};panel('legacy-panel');renderBondEvent();return true}
function renderBondEvent(){$('legacy-panel').classList.remove('monument-cinema');const sc=legacy.bondScene;if(!sc)return;const n=survivors.find(n=>n.id===sc.id),event=bondProfiles[sc.id].events[sc.level===2?0:1],choices=$('legacy-choice-list');$('legacy-speaker').textContent=n.name+' · '+sc.level+' HEARTS';$('legacy-title').textContent=event[0];$('legacy-text').textContent=sc.choice===null?event[1]:event[3][sc.choice];$('legacy-objective').textContent='A quiet moment at '+settlements[n.home].name;choices.innerHTML='';$('legacy-feedback').textContent='';const next=$('legacy-advance');next.classList.toggle('hidden',sc.choice===null);next.disabled=false;next.textContent='Keep this memory';if(sc.choice===null)event[2].forEach((label,i)=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(!legacyCanTalk(sc.id))return;sc.choice=i;renderBondEvent()};choices.appendChild(b)});next.onclick=()=>{if(!legacyCanTalk(sc.id)||sc.choice===null)return;const s=bondState(sc.id);if(s.events.includes(sc.level))return;s.events.push(sc.level);s.choices[sc.level]=sc.choice;n.friend=Math.min(100,n.friend+8);legacy.bondScene=null;closePanels();saveSurvivorHearts();saveLegacyGame(false);notify('A shared memory with '+n.name+' · +8 friendship')}}
function validateBondSave(d){if(d.playerName!==undefined&&(typeof d.playerName!=='string'||d.playerName.length>24))throw Error('Invalid adventurer name.');if(d.bonds===undefined)return;if(!d.bonds||typeof d.bonds!=='object'||Array.isArray(d.bonds))throw Error('Invalid friendship memories.');for(const [id,b]of Object.entries(d.bonds)){if(!Object.hasOwn(bondProfiles,id)||!b||!Array.isArray(b.events)||b.events.length>2||b.events.some(n=>![2,4].includes(n))||!b.preferences||typeof b.preferences!=='object'||!b.choices||typeof b.choices!=='object')throw Error('Invalid heart event.');for(const [gift,type]of Object.entries(b.preferences))if(!Object.hasOwn(foods,gift)||!['loved','liked','neutral','disliked'].includes(type))throw Error('Invalid gift notes.');for(const [level,choice]of Object.entries(b.choices))if(!['2','4'].includes(level)||![0,1].includes(choice))throw Error('Invalid heart choice.')}for(const m of d.monuments)if(m.golden!==undefined&&typeof m.golden!=='boolean'||m.seen!==undefined&&typeof m.seen!=='boolean'||m.name!==undefined&&(typeof m.name!=='string'||m.name.length>24))throw Error('Invalid memorial inscription.')}
function dismissMonumentScene(){if(!legacy.ready||$('legacy-panel').classList.contains('hidden'))return;if(legacy.memorialScene){const m=legacy.monuments.find(m=>m.id===legacy.memorialScene.id);if(m)m.seen=true;legacy.memorialScene=null}legacy.bondScene=null;legacy.scene=null;legacy.powerScene=null}
function rememberBondChoice(n){const b=bondState(n.id),choice=b.choices[2]||0,lines={mira:['“I found a little pot for the seeds we promised to plant together.”','“I kept my sister’s drawing safe, just like you said. Thank you for understanding.”'],rowan:['“I checked the knots with your method today. It was easier knowing I was not alone.”','“I remembered what you said about keeping people safe. I let myself rest.”'],bram:['“I left another chair by the pump. You can sit with me whenever you like.”','“I remembered another tunnel story for you. Stay for a cup?”'],iona:['“The lantern stayed on last night. I thought of what you said about someone finding us.”','“I actually rested in that bed. The shelter survived an hour without me.”'],suri:['“I saw someone wave back at the flag today. I thought of you.”','“Our higher flag caught the sunrise. You should see it.”'],tavi:['“I named today’s supper Something That Is Not Charcoal. You inspired it.”','“I tried your supper again. It means a lot that you believed in me.”'],elian:['“I moved my bag under the bed. I think I am finally staying.”','“I unpacked the last of my things today. Thank you for giving me time.”']};return(lines[n.id]||['“I remember what you said. Thank you for listening.”'])[choice]}

// A living trail: physical travel, witnessed powers and ordinary days with friends.
