function initializeLivingWorld(){ensureTrailBridges();$('survivor-witness-button').onclick=()=>activeSurvivor&&openWitnessMemory(activeSurvivor.id);$('survivor-follow-button').onclick=toggleJourneyFollower;$('survivor-daily-button').onclick=deliverTrailErrand}
function ensureTrailBridges(){legacy.trailBridges=[];for(const [left,right]of [[260,312],[372,405],[540,565],[650,674],[850,885],[1090,1130],[1960,2000],[2160,2200]]){let liquid=false;for(let x=left;x<right;x++)if([29,30,31].some(y=>[8,9].includes(get(x,y)))){liquid=true;break}if(!liquid)continue;const y=28;for(let x=left-2;x<=right+2;x++){if(get(x,y)===0||[6,8,9].includes(get(x,y)))set(x,y,17)}legacy.trailBridges.push({left:left-2,right:right+2,y})}}
function journeyState(n){if(!n.journey)n.journey={mode:'home',zone:[0,1,3,0,6,5,1][survivorProfiles.findIndex(v=>v.id===n.id)]||0,rest:0,follow:false,vy:0,ground:false,stuck:0,chat:0};return n.journey}
function safeTrailFloor(tx,near){tx=Math.max(2,Math.min(W-3,Math.floor(tx)));const sy=surface[tx];for(let y=Math.max(-SKY+3,Math.floor(near===undefined?sy-28:near-5));y<Math.min(H-4,(near===undefined?sy+8:near+14));y++){const v=get(tx,y);if((solid(tx,y)||v===17)&&![8,9].includes(get(tx,y-1))&&!solid(tx,y-1)&&!solid(tx,y-2))return y*T}return null}
function journeyWalk(n,goal,dt){const j=journeyState(n),dx=goal-n.x;if(Math.abs(dx)<12){n.moving=false;n.face=p.x<n.x?-1:1;return true}j.watchTime=(j.watchTime||0)+dt;if(j.watchX===undefined)j.watchX=n.x;if(j.watchTime>4){if(Math.abs(n.x-j.watchX)<65)startJourneyClimb(n,Math.sign(dx));j.watchTime=0;j.watchX=n.x;if(j.climb)return false}const dir=Math.sign(dx),next=n.x+dir*22,ty=n.y/T,floor=safeTrailFloor(next/T,ty);if(floor===null||floor>n.y+90){n.moving=false;n.activity='Waiting for a safe path · bridge needed';j.stuck+=dt;if(j.stuck>2.5)startJourneyClimb(n,dir);return false}if(activeArena&&next>activeArena.left*T-65&&next<activeArena.right*T+65){n.moving=false;n.activity='Waiting for the arena gates to open';return false}const body={x:n.x-n.w/2,y:n.y-n.h,w:n.w,h:n.h,vx:dir*(j.follow?115:76),vy:j.vy,ground:j.ground};const blocked=solid(Math.floor(next/T),Math.floor((n.y-10)/T));if(j.ground&&(blocked||floor<n.y-5||j.stuck>.4))body.vy=-365;const old=n.x;physics(body,dt);n.x=body.x+n.w/2;n.y=body.y+n.h;j.vy=body.vy;j.ground=body.ground;n.face=dir;n.moving=Math.abs(n.x-old)>.1;if(n.moving){n.walk+=dt*9;j.stuck=0}else{j.stuck+=dt;if(j.stuck>2.5)startJourneyClimb(n,dir)}if(n.y>(surface[Math.floor(n.x/T)]+28)*T){n.moving=false;n.activity='Resting in a sheltered hollow';j.vy=0}return false}
function tickSurvivorJourney(n,dt){if(!legacy.ready)return false;const j=journeyState(n),home=settlements[n.home],phase=time%240;for(const key of ['speechTime','powerTime','reactionCooldown'])n[key]=Math.max(0,(n[key]||0)-dt);if(!n.speechTime)n.speech='';if(j.climb){tickJourneyClimb(n,dt);return true}n.bubble=Math.max(0,n.bubble-dt);if(activeArena&&n.x>activeArena.left*T-30&&n.x<activeArena.right*T+30){n.x=(n.x<activeArena.center*T?activeArena.left-4:activeArena.right+4)*T;n.y=safeTrailFloor(n.x/T)||surface[Math.floor(n.x/T)]*T;j.vy=0;n.activity='Taking shelter outside the arena';return true}if(n.speechTime>0){n.moving=false;return true}if(j.follow){if(Math.hypot(p.x-n.x,p.y+p.h-n.y)>1600){n.moving=false;n.activity='Waiting on the trail · you went ahead';return true}n.activity='Traveling with '+legacy.playerName;const goal=p.x-p.face*55;journeyWalk(n,goal,dt);return true}if(j.mode==='home'){const slot=n.id==='elian'?0:survivorProfiles[n.home*2].id===n.id?-1:1;if(phase<25||phase>=185){const goal=(home.tile+slot*6)*T,dx=goal-n.x;n.x+=Math.sign(dx)*Math.min(Math.abs(dx),34*dt);n.y=home.floor*T;n.moving=Math.abs(dx)>3;n.walk+=n.moving?dt*7:0;n.activity=phase>=185?'Sleeping':'Breakfast by the fire';return true}n.activity='Packing for the trail';const goal=home.liftTile*T,dx=goal-n.x;n.x+=Math.sign(dx)*Math.min(Math.abs(dx),45*dt);n.y=home.floor*T;n.face=Math.sign(dx)||1;n.moving=Math.abs(dx)>3;n.walk+=dt*8;if(Math.abs(dx)<4)j.mode='lift';return true}if(j.mode==='lift'){n.x=home.liftTile*T;const dy=home.surfaceFloor*T-n.y;n.y+=Math.sign(dy)*Math.min(Math.abs(dy),150*dt);n.moving=false;n.activity='Riding the rope lift';if(Math.abs(dy)<3){j.mode='trail';j.ground=false;j.vy=0}return true}if(phase>=185){n.activity='Sleeping at a roadside camp';n.moving=false;j.mode='camp';const body={x:n.x-n.w/2,y:n.y-n.h,w:n.w,h:n.h,vx:0,vy:j.vy};physics(body,dt);n.y=body.y+n.h;j.vy=body.vy;j.ground=body.ground;return true}if(phase<25){n.activity='Making breakfast on the road';n.moving=false;return true}j.mode='trail';if(j.rest>0){j.rest=Math.max(0,j.rest-dt);n.moving=false;const actions={mira:'Collecting wild seeds',rowan:'Checking trail bridges',bram:'Studying an old mine entrance',iona:'Preparing medicine for travelers',suri:'Watching the wind',tavi:'Cooking at a roadside fire',elian:'Sketching the new roads'};n.activity=actions[n.id];return true}const camp=trailCamps[j.zone],goal=camp.x*T+(survivorProfiles.findIndex(v=>v.id===n.id)%3-1)*35;n.activity='Walking to '+camp.name;if(journeyWalk(n,goal,dt)){j.rest=18;j.zone=(j.zone+(n.home===1?2:1))%7;n.activity='Arrived at '+camp.name}return true}
function carryJourneyFollowers(){for(const n of survivors)if(n.journey?.follow){n.x=p.x-30;n.y=p.y+p.h;n.journey.vy=0;n.journey.ground=false}}
function journeyLocation(n){return biomes[biomeAt(n.x)].name+' · x '+Math.floor(n.x/T)+', y '+Math.floor(n.y/T)}
function witnessState(id){return legacy.witnesses[id]||(legacy.witnesses[id]={seen:[],heard:[],choices:{},last:''})}
function survivorCanSee(n){const dx=p.x+p.w/2-n.x,dy=p.y+p.h/2-(n.y-15);if(Math.hypot(dx,dy)>310)return false;const steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/15));for(let i=1;i<steps;i++){const x=Math.floor((n.x+dx*i/steps)/T),y=Math.floor((n.y-15+dy*i/steps)/T);if(solid(x,y))return false}return true}
function witnessSurvivorPower(id,mode){if(!legacy.ready||!started||paused||!Object.hasOwn(witnessedPowers,id))return false;if(id==='omniFists'&&!adminUnlocked)return false;let reacted=false;for(const n of survivors){if(!survivorCanSee(n))continue;const s=witnessState(n.id),fresh=!s.seen.includes(id);if(!fresh&&(n.reactionCooldown||0)>0)continue;if(fresh)s.seen.push(id);s.last=id;n.speech=witnessedPowers[id].first;n.speechTime=4;n.powerSeen=id;n.powerTime=4;n.reactionCooldown=22;n.line=n.speech;n.moving=false;if(id==='shadowFists'||id==='shadowForm'){if(fresh&&!legacy.pendingWitness)legacy.pendingWitness={npc:n.id,power:id}}reacted=true}return reacted}
function renderPowerFriendship(n){const s=witnessState(n.id),unheard=s.seen.slice().reverse().find(id=>!s.heard.includes(id)),b=$('survivor-witness-button');b.classList.toggle('hidden',!unheard);b.textContent='About what you saw…';if(unheard)b.textContent='About '+(unheard==='shadowForm'?'Eclipse Form':items[unheard]?.name||unheard)+'…';$('survivor-witness-note').textContent=s.seen.length?'Powers witnessed: '+s.seen.length+' · Shared power memories: '+s.heard.length:'Use a fighting style nearby. Your friends will notice.';const j=journeyState(n),follow=$('survivor-follow-button');follow.disabled=n.friend<40;follow.textContent=j.follow?'Stay here · end our journey':n.friend>=40?'Come explore with me':'Invite along · needs two hearts';const e=trailErrand(n);$('survivor-daily-detail').textContent='Today’s trail request · '+survivorCostText(e.need)+' → '+survivorCostText(e.reward)+' · +5 friendship';$('survivor-daily-button').disabled=e.done||!survivorCanPay(e.need);$('survivor-daily-button').textContent=e.done?'Supplies shared today':'Deliver trail supplies'}
function openWitnessMemory(id,power){const n=legacyCanTalk(id);if(!n)return false;const s=witnessState(id),key=power||s.seen.slice().reverse().find(k=>!s.heard.includes(k));if(!key||!s.seen.includes(key)||s.heard.includes(key))return false;legacy.powerScene={npc:id,power:key,choice:null};panel('legacy-panel');renderWitnessMemory();return true}
function renderWitnessMemory(){const sc=legacy.powerScene;if(!sc)return;const n=survivors.find(n=>n.id===sc.npc),d=witnessedPowers[sc.power];$('legacy-panel').classList.remove('monument-cinema');$('legacy-speaker').textContent=n.name+' · A POWER WITNESSED';$('legacy-title').textContent=d.title;$('legacy-text').textContent=sc.choice===null?d.text:d.answers[sc.choice];$('legacy-objective').textContent=n.role+' · '+journeyLocation(n);$('legacy-feedback').textContent='';const list=$('legacy-choice-list');list.innerHTML='';const next=$('legacy-advance');next.classList.toggle('hidden',sc.choice===null);next.textContent='Remember this together';next.disabled=false;if(sc.choice===null)d.choices.forEach((label,i)=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{if(legacyCanTalk(sc.npc)){sc.choice=i;renderWitnessMemory()}};list.appendChild(b)});next.onclick=()=>{if(!legacyCanTalk(sc.npc)||sc.choice===null)return;const s=witnessState(sc.npc);if(s.heard.includes(sc.power))return;s.heard.push(sc.power);s.choices[sc.power]=sc.choice;n.friend=Math.min(100,n.friend+5);survivorGive(d.reward);n.line=d.answers[sc.choice];legacy.powerScene=null;closePanels();saveSurvivorHearts();inventory();updatePack();saveLegacyGame(false);notify('A power remembered with '+n.name+' · +5 friendship')}}
function toggleJourneyFollower(){const n=activeSurvivor;if(!n||!legacyCanTalk(n.id)||n.friend<40)return false;const next=!journeyState(n).follow;for(const person of survivors)journeyState(person).follow=false;journeyState(n).follow=next;if(!next)journeyState(n).mode='trail';n.speech=next?'I am coming with you. Let us see what is still out there.':'I will keep the fire going. Come find me again.';n.speechTime=3;closePanels();saveLegacyGame(false);notify(next?n.name+' is traveling with you':n.name+' will continue their own journey');return true}
function trailErrand(n){const day=survivorDay();let e=legacy.errands[n.id];if(!e||e.day!==day){const index=survivorProfiles.findIndex(v=>v.id===n.id),zone=biomeAt(n.x),need=(day+index)%3===0?{3:8}:(day+index)%3===1?{[20+zone]:3}:{berries:4};e=legacy.errands[n.id]={day,need,reward:{[n.favorite]:2,torch:2},done:false}}return e}
function deliverTrailErrand(){const n=activeSurvivor;if(!n||!legacyCanTalk(n.id))return false;const e=trailErrand(n);if(e.done||!survivorCanPay(e.need))return false;survivorPay(e.need);survivorGive(e.reward);e.done=true;n.friend=Math.min(100,n.friend+5);n.line='“You remembered what I needed. The trail feels easier with a friend.”';saveSurvivorHearts();inventory();updatePack();renderSurvivorPanel();saveLegacyGame(false);return true}
function journeyGreeting(n){if(n.speechTime>0&&n.speech)return n.speech;const s=legacy.witnesses[n.id];if(s?.heard.length&&survivorDay()%4===1){const key=s.heard.at(-1);return witnessedPowers[key].answers[s.choices[key]||0]}if(n.journey?.follow)return '“Where are we going today, '+legacy.playerName+'? I will stay on the trail if you take to the sky.”';if(n.journey&&n.journey.mode!=='home'&&survivorDay()%3===2)return '“I never thought I would see '+biomes[biomeAt(n.x)].name+' again. It is different when you have someone to tell about it.”';return ''}
function tickLivingWorld(dt){if(!legacy.ready)return;if(legacy.powerScene&&$('legacy-panel').classList.contains('hidden'))legacy.powerScene=null;if(legacy.pendingWitness&&!paused&&!boss&&!bossIntro&&!adminReckoning&&!legacy.scene&&!legacy.memorialScene&&!legacy.bondScene&&!legacy.powerScene&&!legacy.trial){const pending=legacy.pendingWitness,n=survivors.find(n=>n.id===pending.npc),danger=slimes.some(e=>e.hp>0&&Math.hypot(e.x-p.x,e.y-p.y)<230);if(n&&Math.hypot(n.x-p.x,n.y-(p.y+p.h))<75&&!danger){legacy.pendingWitness=null;openWitnessMemory(n.id,pending.power)}else if(!n||Math.hypot(n.x-p.x,n.y-p.y)>600)legacy.pendingWitness=null}for(const n of survivors){const j=journeyState(n);j.chat=Math.max(0,j.chat-dt);if(j.chat<=0&&!n.speechTime){const friend=survivors.find(other=>other!==n&&Math.hypot(n.x-other.x,n.y-other.y)<60);if(friend&&time%240>100){n.speech='Good to see you, '+friend.name+'. There is room by the fire.';n.speechTime=3;j.chat=32}}}legacy.mapTimer+=dt;if(legacy.mapTimer>.5){legacy.mapTimer=0;drawMiniMap();drawJourneyMiniMap()}}
function renderJourneyJournal(){const root=$('journey-journal');root.innerHTML='';for(const n of survivors){const row=document.createElement('div');row.className='legacy-journal-entry';const h=document.createElement('h3');h.textContent=n.name+' · '+n.activity;const p1=document.createElement('p');p1.textContent=journeyLocation(n)+' · '+(n.journey?.follow?'Traveling with you':n.journey?.mode==='home'?'At home':'On the road')+' · '+(legacy.witnesses[n.id]?.heard.length||0)+' power memories';const b=document.createElement('button');b.textContent=legacy.tracked===n.id?'Tracked on the map':'Track this friend';b.onclick=()=>{legacy.tracked=n.id;drawMiniMap();drawJourneyMiniMap();renderJourneyJournal();saveLegacyGame(false)};row.appendChild(h);row.appendChild(p1);row.appendChild(b);root.appendChild(row)}}
function drawJourneyMiniMap(){const c=$('world-map').getContext('2d');for(const n of survivors){const x=n.x/(W*T)*216;c.fillStyle=legacy.tracked===n.id?'#ffe598':'#a5dfb2';c.fillRect(Math.round(x)-1,28,legacy.tracked===n.id?4:2,legacy.tracked===n.id?5:3)}if(legacy.tracked){const n=survivors.find(n=>n.id===legacy.tracked);if(n){c.fillStyle='#ffe6af';c.textAlign='center';c.font='8px monospace';c.fillText(n.name+' · x '+Math.floor(n.x/T),108,40)}}}
function drawWitnessBubble(n,x,y){if(!n.speech||!n.speechTime)return;const text=n.speech,lines=[];let line='';for(const word of text.split(' ')){if((line+' '+word).trim().length>43){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);ctx.save();ctx.textAlign='center';ctx.font='10px monospace';const width=Math.min(290,Math.max(...lines.map(s=>s.length))*6+18),left=Math.max(4,Math.min(vw-width-4,x-width/2));ctx.fillStyle='#112a2de8';ctx.fillRect(left,y-85,width,lines.length*14+12);ctx.strokeStyle=n.powerSeen?witnessedPowers[n.powerSeen]?.color||'#c8d9ae':'#c8d9ae';ctx.lineWidth=1;ctx.strokeRect(left+.5,y-84.5,width-1,lines.length*14+11);ctx.fillStyle='#f6e5c6';lines.forEach((s,i)=>ctx.fillText(s,left+width/2,y-70+i*14));ctx.restore()}
function drawLivingWorld(){ctx.save();for(let i=0;i<trailCamps.length;i++){const camp=trailCamps[i],floor=safeTrailFloor(camp.x)||surface[camp.x]*T,x=camp.x*T-camera.x,y=floor-camera.y;if(x< -160||x>vw+160||y< -120||y>vh+120)continue;ctx.fillStyle='#6b654e';ctx.fillRect(x-30,y-24,4,24);ctx.fillRect(x+30,y-24,4,24);ctx.fillStyle=biomes[i].color;for(let j=0;j<6;j++)ctx.fillRect(x-38+j*6,y-44-j*3,76-j*12,5);ctx.fillStyle='#36443d';ctx.fillRect(x-25,y-17,50,15);ctx.fillStyle='#bdab7c';ctx.fillRect(x-21,y-14,42,4);ctx.fillStyle='#76604b';ctx.fillRect(x+46,y-5,25,5);ctx.fillStyle='#f3bd77';ctx.fillRect(x+53,y-14,6,9);ctx.textAlign='center';ctx.font='9px monospace';ctx.fillStyle='#e8d4aa';ctx.fillText(camp.name,x,y-64)}for(const bridge of legacy.trailBridges){const x=bridge.left*T-camera.x,y=bridge.y*T-camera.y,w=(bridge.right-bridge.left+1)*T;if(x+w<0||x>vw||y< -50||y>vh+50)continue;ctx.fillStyle='#917449';for(let xx=0;xx<w;xx+=60)ctx.fillRect(x+xx,y-23,3,27);ctx.strokeStyle='#b6a17a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y-23);ctx.lineTo(x+w,y-23);ctx.stroke()}for(const n of survivors){const x=n.x-camera.x,y=n.y-camera.y;if(n.journey?.climb){const climb=n.journey.climb;ctx.strokeStyle='#bea77b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(climb.sx-camera.x,climb.sy-camera.y);ctx.lineTo(climb.sx-camera.x,climb.top-camera.y);ctx.lineTo(climb.tx-camera.x,climb.top-camera.y);ctx.lineTo(x,y);ctx.stroke()}if(n.powerTime>0){const id=n.powerSeen,d=witnessedPowers[id];ctx.strokeStyle=d.color;ctx.lineWidth=2;ctx.globalAlpha=.65;if(id==='shadowFists'||id==='shadowForm'){ctx.fillStyle='#30213c';for(let j=0;j<5;j++)ctx.fillRect(x-24+j*9,y-5-Math.sin(j)*8,7,5);ctx.fillStyle='#c6a5f0';ctx.fillRect(x+11,y-11,3,2);ctx.fillRect(x+17,y-11,3,2)}else if(id==='waterFists'){ctx.beginPath();ctx.ellipse(x,y-2,25,6,0,0,Math.PI*2);ctx.stroke()}else if(id==='lineOfCode'){ctx.font='9px monospace';ctx.fillStyle=d.color;ctx.fillText('friend.safe = true;',x-45,y-53)}else{for(let j=0;j<7;j++){const a=time*2+j*Math.PI*2/7;ctx.fillStyle=d.color;ctx.fillRect(x+Math.cos(a)*23,y-18+Math.sin(a)*21,2,3)}}ctx.globalAlpha=1}if(n.journey?.mode==='camp'&&time%240>=185){ctx.fillStyle='#675743';ctx.fillRect(x-21,y-4,42,4);ctx.fillStyle=n.shirt;ctx.fillRect(x-18,y-8,30,4);ctx.fillStyle='#edb56b';ctx.fillRect(x+28,y-9,5,8)}if(legacy.tracked===n.id){ctx.fillStyle='#ffe6a2';ctx.fillRect(x-2,y-60,4,7);ctx.fillRect(x-5,y-56,10,2)}}ctx.restore()}
function snapshotJourneys(){return survivors.map(n=>({id:n.id,x:n.x,y:n.y,journey:{mode:journeyState(n).mode,zone:journeyState(n).zone,rest:journeyState(n).rest,follow:journeyState(n).follow}}))}
function restoreJourneys(values){for(const n of survivors){n.journey=null;n.speech='';n.speechTime=0;const v=values?.find(v=>v.id===n.id);if(v){n.x=v.x;n.y=v.y;n.journey={mode:v.journey.mode,zone:v.journey.zone,rest:v.journey.rest,follow:v.journey.follow,vy:0,ground:false,chat:0,stuck:0};const body={x:n.x-n.w/2,y:n.y-n.h,w:n.w,h:n.h};if(collision(body)){const f=safeTrailFloor(n.x/T);if(f!==null)n.y=f;else{n.x=settlements[n.home].liftTile*T;n.y=settlements[n.home].surfaceFloor*T;n.journey.mode='trail'}}}}}
function validateLivingSave(d){for(const key of ['witnesses','errands'])if(d[key]!==undefined&&(!d[key]||typeof d[key]!=='object'||Array.isArray(d[key])))throw Error('Invalid living-world data.');const known=['mira','rowan','bram','iona','suri','tavi','elian'];for(const [id,s]of Object.entries(d.witnesses||{})){if(!known.includes(id)||!s||!Array.isArray(s.seen)||!Array.isArray(s.heard)||s.seen.length>9||s.heard.length>9||s.seen.some(k=>!Object.hasOwn(witnessedPowers,k))||s.heard.some(k=>!s.seen.includes(k))||!s.choices||typeof s.choices!=='object')throw Error('Invalid power memories.');for(const [key,v]of Object.entries(s.choices))if(!Object.hasOwn(witnessedPowers,key)||![0,1].includes(v))throw Error('Invalid power choice.')}for(const [id,e]of Object.entries(d.errands||{})){if(!known.includes(id)||!e||!Number.isInteger(e.day)||e.day<0||typeof e.done!=='boolean')throw Error('Invalid trail request.');for(const values of [e.need,e.reward]){if(!values||typeof values!=='object'||Array.isArray(values)||Object.keys(values).length>4)throw Error('Invalid trail supplies.');for(const [key,n]of Object.entries(values))if(!Object.hasOwn(bag,key)||!Number.isInteger(n)||n<1||n>100)throw Error('Invalid trail supplies.')}}if(d.journeys!==undefined){if(!Array.isArray(d.journeys)||d.journeys.length>7)throw Error('Invalid journeys.');for(const v of d.journeys)if(!v||!known.includes(v.id)||!Number.isFinite(v.x)||v.x<0||v.x>W*T||!Number.isFinite(v.y)||v.y<-SKY*T||v.y>H*T||!v.journey||!['home','lift','trail','camp'].includes(v.journey.mode)||!Number.isInteger(v.journey.zone)||v.journey.zone<0||v.journey.zone>6||typeof v.journey.follow!=='boolean'||!Number.isFinite(v.journey.rest)||v.journey.rest<0||v.journey.rest>120)throw Error('Invalid traveler position.')}}
function startJourneyClimb(n,dir){const j=journeyState(n);if(j.climb)return;for(let distance=4;distance<=10;distance+=2){const tx=n.x+dir*distance*T;if(tx<50||tx>(W-3)*T)continue;if(activeArena&&tx>activeArena.left*T-60&&tx<activeArena.right*T+60)continue;const floor=safeTrailFloor(tx/T);if(floor===null)continue;let top=Math.min(n.y,floor)-90;for(let x=Math.min(n.x,tx);x<=Math.max(n.x,tx);x+=T){const surfaceFloor=safeTrailFloor(x/T);if(surfaceFloor!==null)top=Math.min(top,surfaceFloor-75)}j.climb={sx:n.x,sy:n.y,tx,ty:floor,top,age:0};j.stuck=0;j.vy=0;n.activity='Using a climbing rope';return}}
function tickJourneyClimb(n,dt){const j=journeyState(n),c=j.climb;c.age+=dt;const t=Math.min(1,c.age/2),ease=v=>v*v*(3-2*v);if(t<.25){n.x=c.sx;n.y=c.sy+(c.top-c.sy)*ease(t*4)}else if(t<.75){n.x=c.sx+(c.tx-c.sx)*ease((t-.25)*2);n.y=c.top}else{n.x=c.tx;n.y=c.top+(c.ty-c.top)*ease((t-.75)*4)}n.moving=false;n.face=Math.sign(c.tx-c.sx);n.activity='Using a climbing rope';if(t>=1){j.climb=null;j.ground=true;n.y=c.ty}}
